                    isFirstTime = false
                elseif not isfile then
                    local ok, res = pcall(readfile, "HDLE_Combat_Played.txt")
                    if ok and res == "played" then isFirstTime = false end
                end
            end
            
            if isFirstTime then
                if writefile then pcall(writefile, "HDLE_Combat_Played.txt", "played") end
                State.Combat.Aimbot.AutoShoot = true
                State.Combat.ESP.Enabled = true
                State.Combat.ESP.Boxes = true
                State.Combat.ESP.Names = true
                UpdateAllCombatUI()
                
